1	import {
2	  component$,
3	  useSignal,
4	  useStore,
5	  useVisibleTask$,
6	  $,
7	  noSerialize,
8	  Slot,
9	  type NoSerialize,
10	  type PropFunction,
11	} from "@builder.io/qwik";
12	import { useConvexClient } from "../../utils/convex-context";
13	import {
14	  canRecord,
15	  formatDuration,
16	  startRecording,
17	  transcribeRecording,
18	  type RecorderHandle,
19	} from "../../utils/voice-notes";
20	import { ApplicationNotice } from "./application-notice";
21	import type { AppError } from "../../types/application-errors";
22	import { normalizeApplicationError } from "../../utils/application-errors";
23	
24	interface ChatComposerProps {
25	  /** Current draft. The parent owns it, so a caller can prefill or clear it. */
26	  value: string;
27	  onValueChange$: PropFunction<(value: string) => void>;
28	  onSend$: PropFunction<() => void>;
29	  placeholder?: string;
30	  /** Work is in flight: the send key becomes a stop key when `onStop$` exists. */
31	  busy?: boolean;
32	  onStop$?: PropFunction<() => void>;
33	  disabled?: boolean;
34	  /** Terms likely to appear, to help the transcriber with proper nouns. */
35	  transcriptionHint?: string;
36	  /** Hide the microphone where dictation makes no sense. */
37	  allowVoice?: boolean;
38	  /** Accessible name for the text box. */
39	  label?: string;
40	  /** Names the send key where "Send" is the wrong verb — "Steer", say. */
41	  sendLabel?: string;
42	}
43	
44	interface ComposerStore {
45	  phase: "idle" | "recording" | "transcribing";
46	  elapsedMs: number;
47	  level: number;
48	  paused: boolean;
49	  error: AppError | null;
50	  handle: NoSerialize<RecorderHandle> | null;
51	  /** Lets the writer stop an in-flight transcription. */
52	  transcribeAbort: NoSerialize<AbortController> | null;
53	}
54	
55	/**
56	 * The place a writer speaks from — one surface holding the text, the
57	 * microphone and the send key.
58	 *
59	 * Modelled on the composers in modern chat clients, for the ordinary reason
60	 * that writers already know how those behave: Enter sends, Shift+Enter breaks
61	 * the line, the box grows with the text instead of scrolling inside three
62	 * fixed rows, and the controls live inside the field rather than stacked
63	 * underneath it as separate widgets.
64	 *
65	 * Two departures from the recorder it replaces:
66	 *
67	 *   - **Dictation lands in the draft, not in a review box.** The old recorder
68	 *     transcribed into its own textarea with keep/discard buttons. That is the
69	 *     right shape when the transcript becomes a note directly, but here the
70	 *     destination is already an editable field the writer is looking at — a
71	 *     second one asks them to approve their words twice.
72	 *   - **Recording happens in the toolbar.** Replacing the composer with the
73	 *     recorder hides whatever was already typed, and dictation is usually
74	 *     *adding* to a draft rather than starting one.
75	 */
76	export const ChatComposer = component$<ChatComposerProps>((props) => {
77	  const clientSig = useConvexClient();
78	  const inputRef = useSignal<HTMLTextAreaElement>();
79	  const canDictate = useSignal(false);
80	  const store = useStore<ComposerStore>({
81	    phase: "idle",
82	    elapsedMs: 0,
83	    level: 0,
84	    paused: false,
85	    error: null,
86	    handle: null,
87	    transcribeAbort: null,
88	  });
89	
90	  // eslint-disable-next-line qwik/no-use-visible-task
91	  useVisibleTask$(({ track, cleanup }) => {
92	    canDictate.value = props.allowVoice !== false && canRecord();
93	    track(() => store.phase);
94	    if (store.phase !== "recording") return;
95	    // The handle counts active audio, so a pause freezes the elapsed.
96	    const timer = setInterval(() => {
97	      store.elapsedMs = store.handle?.elapsed() ?? 0;
98	      store.level = store.handle?.level() ?? 0;
99	    }, 100);
100	    cleanup(() => clearInterval(timer));
101	  });
102	
103	  // Grow with the content up to the CSS max-height, then scroll. Driven off
104	  // the value rather than the input event so a programmatic prefill (a
