  case_id: string;
  query: string;
  context: string;
  candidateSources: CandidateSource[];
}

interface LlmVerdict {
  label: string;
  score: number | null;
  explanation: string;
}

interface SourceScore {
  case_id: string;
  query: string;
  url: string;
  title: string;
  ground_truth: "relevant" | "irrelevant";
  predicted: "relevant" | "irrelevant" | "?";
  correct: boolean;
  explanation: string;
}

interface RowSummary {
  case_id: string;
  accuracy: number;
  precision_relevant: number | null;
  recall_relevant: number | null;
  n: number;
  tp: number;
